    13	@Component
    14	public class LoadDriver {
    15	
    16	    private static final Logger log = LoggerFactory.getLogger(LoadDriver.class);
    17	
    18	    private final RestTemplate rest;
    19	    private final boolean enabled;
    20	    private final String[] paths;
    21	    private int cursor = 0;
    22	
    23	    public LoadDriver(
    24	            RestTemplate rest,
    25	            org.springframework.core.env.Environment env) {
    26	        this.rest = rest;
    27	        this.enabled = Boolean.parseBoolean(env.getProperty("app.load.enabled", "false"));
    28	        String configured = env.getProperty("app.load.paths", "/api/orders/1");
    29	        this.paths = configured.split(",");
    30	    }
    31	
    32	    @Scheduled(fixedDelayString = "${app.load.interval-ms:1000}")
    33	    public void tick() {
    34	        if (!enabled) {
    35	            return;
    36	        }
    37	        String path = paths[cursor++ % paths.length];
    38	        try {
    39	            rest.getForEntity("http://127.0.0.1:8080" + path, String.class);
