      .map((line) => {
        const m = line.match(/^(\S+)\t(\S+?)(?:[+-]\d{2}:\d{2}|Z)\t(.*)$/);
        return m ? `${m[1]}\t${new Date(m[2]).toISOString()}\t${m[3]}` : line;
